inline void lower_STORE_SPLIT_TVALUE(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;
    auto& regs = lowering.regs;
    (void)index;
    (void)next;

    auto addr_offset = HAS_OP_D(inst) ? lowering.intOp(OP_D(inst)) : 0;
    auto tag_lhs = OP_A(inst).kind == IrOpKind::Inst ? dword[lowering.regOp(OP_A(inst)) + offsetof(TValue, tt) + addr_offset] : luauRegTag(vmRegOp(OP_A(inst)));
    build.mov(tag_lhs, lowering.tagOp(OP_B(inst)));
    if (lowering.tagOp(OP_B(inst)) == LUA_TBOOLEAN)
    {
        auto value_lhs = OP_A(inst).kind == IrOpKind::Inst ? dword[lowering.regOp(OP_A(inst)) + offsetof(TValue, value) + addr_offset] : luauRegValueInt(vmRegOp(OP_A(inst)));
        if (OP_C(inst).kind == IrOpKind::Constant)
        {
            build.mov(value_lhs, lowering.intOp(OP_C(inst)));
        }
        else
        {
            build.mov(value_lhs, lowering.regOp(OP_C(inst)));
        }
    }
    else if (lowering.tagOp(OP_B(inst)) == LUA_TNUMBER)
    {
        auto value_lhs = OP_A(inst).kind == IrOpKind::Inst ? qword[lowering.regOp(OP_A(inst)) + offsetof(TValue, value) + addr_offset] : luauRegValue(vmRegOp(OP_A(inst)));
        if (OP_C(inst).kind == IrOpKind::Constant)
        {
            ScopedRegX64 tmp{regs, SizeX64::xmmword};
            build.vmovsd(tmp.reg, build.f64(lowering.doubleOp(OP_C(inst))));
            build.vmovsd(value_lhs, tmp.reg);
        }
        else
        {
            build.vmovsd(value_lhs, lowering.regOp(OP_C(inst)));
        }
    }
    else if (lowering.tagOp(OP_B(inst)) == LUA_TINTEGER)
    {
        auto value_lhs = OP_A(inst).kind == IrOpKind::Inst ? qword[lowering.regOp(OP_A(inst)) + offsetof(TValue, value) + addr_offset] : luauRegValueInt64(vmRegOp(OP_A(inst)));
        if (OP_C(inst).kind == IrOpKind::Constant)
        {
            if (lowering.int64Op(OP_C(inst)) >= INT32_MIN && lowering.int64Op(OP_C(inst)) <= INT32_MAX)
            {
                build.mov(value_lhs, int32_t(lowering.int64Op(OP_C(inst))));
            }
            else
            {
                ScopedRegX64 tmp{regs, SizeX64::qword};
                build.mov64(tmp.reg, lowering.int64Op(OP_C(inst)));
                build.mov(value_lhs, tmp.reg);
            }
        }
        else
        {
            build.mov(value_lhs, lowering.regOp(OP_C(inst)));
        }
    }
    else if (isGCO(lowering.tagOp(OP_B(inst))))
    {
        auto value_lhs = OP_A(inst).kind == IrOpKind::Inst ? qword[lowering.regOp(OP_A(inst)) + offsetof(TValue, value) + addr_offset] : luauRegValue(vmRegOp(OP_A(inst)));
        build.mov(value_lhs, lowering.regOp(OP_C(inst)));
    }
    else
    {
        CODEGEN_ASSERT(!"Unsupported instruction form");
    }
}

