inline void lower_ROUND_NUM(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;
    auto& regs = lowering.regs;
    (void)next;

    inst.regX64 = regs.allocRegOrReuse(SizeX64::xmmword, index, {OP_A(inst)});
    ScopedRegX64 tmp1{regs, SizeX64::xmmword};
    ScopedRegX64 tmp2{regs, SizeX64::xmmword};
    if (!(OP_A(inst).kind == IrOpKind::Inst))
    {
        build.vmovsd(inst.regX64, lowering.memRegDoubleOp(OP_A(inst)));
    }
    else if ((OP_A(inst).kind != IrOpKind::Inst || inst.regX64 != lowering.regOp(OP_A(inst))))
    {
        build.vmovsd(inst.regX64, inst.regX64, lowering.regOp(OP_A(inst)));
    }
    build.vandpd(tmp1.reg, inst.regX64, build.f64x2(-0.0, -0.0));
    build.vmovsd(tmp2.reg, build.i64(0x3fdfffffffffffff));
    build.vorpd(tmp1.reg, tmp1.reg, tmp2.reg);
    build.vaddsd(inst.regX64, inst.regX64, tmp1.reg);
    build.vroundsd(inst.regX64, inst.regX64, inst.regX64, RoundingModeX64::RoundToZero);
}

inline void lower_SIGN_NUM(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;
    auto& regs = lowering.regs;
    (void)next;

    inst.regX64 = regs.allocRegOrReuse(SizeX64::xmmword, index, {OP_A(inst)});
    ScopedRegX64 tmp0{regs, SizeX64::xmmword};
    ScopedRegX64 tmp1{regs, SizeX64::xmmword};
    ScopedRegX64 tmp2{regs, SizeX64::xmmword};
    build.vxorpd(tmp0.reg, tmp0.reg, tmp0.reg);
    build.vcmpltsd(tmp1.reg, lowering.regOp(OP_A(inst)), tmp0.reg);
    build.vmovsd(tmp2.reg, build.f64(-1));
    build.vandpd(tmp1.reg, tmp1.reg, tmp2.reg);
    build.vcmpltsd(inst.regX64, tmp0.reg, lowering.regOp(OP_A(inst)));
    build.vblendvpd(inst.regX64, tmp1.reg, build.f64x2(1, 1), inst.regX64);
}

inline void lower_SIGN_FLOAT(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;
    auto& regs = lowering.regs;
    (void)next;

    inst.regX64 = regs.allocRegOrReuse(SizeX64::xmmword, index, {OP_A(inst)});
    ScopedRegX64 tmp0{regs, SizeX64::xmmword};
    ScopedRegX64 tmp1{regs, SizeX64::xmmword};
    ScopedRegX64 tmp2{regs, SizeX64::xmmword};
    build.vxorps(tmp0.reg, tmp0.reg, tmp0.reg);
    build.vcmpltss(tmp1.reg, lowering.regOp(OP_A(inst)), tmp0.reg);
    build.vmovss(tmp2.reg, build.f32(-1.0f));
    build.vandps(tmp1.reg, tmp1.reg, tmp2.reg);
    build.vcmpltss(inst.regX64, tmp0.reg, lowering.regOp(OP_A(inst)));
    build.vblendvps(inst.regX64, tmp1.reg, build.f32x4(1, 1, 1, 1), inst.regX64);
}

inline void lower_MOD_NUM(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;
    auto& regs = lowering.regs;
    (void)next;

    inst.regX64 = regs.allocRegOrReuse(SizeX64::xmmword, index, {OP_A(inst), OP_B(inst)});
    ScopedRegX64 lhs_tmp{regs};
    if (OP_A(inst).kind == IrOpKind::Constant)
        lhs_tmp.alloc(SizeX64::xmmword);
    RegisterX64 lhs = OP_A(inst).kind == IrOpKind::Constant ? lhs_tmp.reg : lowering.regOp(OP_A(inst));
    if (OP_A(inst).kind == IrOpKind::Constant)
    {
        build.vmovsd(lhs, lowering.memRegDoubleOp(OP_A(inst)));
    }
    if (OP_B(inst).kind == IrOpKind::Inst)
    {
        ScopedRegX64 tmp{regs, SizeX64::xmmword};
        build.vdivsd(tmp.reg, lhs, lowering.memRegDoubleOp(OP_B(inst)));
        build.vroundsd(tmp.reg, tmp.reg, tmp.reg, RoundingModeX64::RoundToNegativeInfinity);
        build.vmulsd(tmp.reg, tmp.reg, lowering.memRegDoubleOp(OP_B(inst)));
        build.vsubsd(inst.regX64, lhs, tmp.reg);
    }
    else
    {
        ScopedRegX64 tmp1{regs, SizeX64::xmmword};
        ScopedRegX64 tmp2{regs, SizeX64::xmmword};
        build.vmovsd(tmp1.reg, lowering.memRegDoubleOp(OP_B(inst)));
        build.vdivsd(tmp2.reg, lhs, tmp1.reg);
        build.vroundsd(tmp2.reg, tmp2.reg, tmp2.reg, RoundingModeX64::RoundToNegativeInfinity);
        build.vmulsd(tmp1.reg, tmp2.reg, tmp1.reg);
        build.vsubsd(inst.regX64, lhs, tmp1.reg);
    }
}

inline void lower_MULADD_NUM(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;
    auto& regs = lowering.regs;
    (void)next;

    if (((build.features & Feature_FMA3) != 0))
    {
        if (OP_A(inst).kind == IrOpKind::Inst)
        {
            inst.regX64 = regs.allocRegOrReuse(SizeX64::xmmword, index, {OP_A(inst)});
        }
        else
        {
            inst.regX64 = regs.allocReg(SizeX64::xmmword, index);
        }
        if (OP_A(inst).kind == IrOpKind::Inst)
        {
            if ((OP_A(inst).kind != IrOpKind::Inst || inst.regX64 != lowering.regOp(OP_A(inst))))
            {
                build.vmovupd(inst.regX64, lowering.regOp(OP_A(inst)));
            }
        }
        else
        {
            build.vmovsd(inst.regX64, lowering.memRegDoubleOp(OP_A(inst)));
        }
        ScopedRegX64 b_reg_tmp{regs};
        if (OP_B(inst).kind == IrOpKind::Constant)
            b_reg_tmp.alloc(SizeX64::xmmword);
        RegisterX64 b_reg = OP_B(inst).kind == IrOpKind::Constant ? b_reg_tmp.reg : lowering.regOp(OP_B(inst));
        if (OP_B(inst).kind == IrOpKind::Constant)
        {
            build.vmovsd(b_reg, lowering.memRegDoubleOp(OP_B(inst)));
        }
        build.vfmadd213pd(inst.regX64, b_reg, lowering.memRegDoubleOp(OP_C(inst)));
    }
    else
    {
        inst.regX64 = regs.allocRegOrReuse(SizeX64::xmmword, index, {OP_A(inst)});
        if (!(OP_A(inst).kind == IrOpKind::Inst) && !(OP_B(inst).kind == IrOpKind::Inst))
        {
            build.vmovsd(inst.regX64, lowering.memRegDoubleOp(OP_A(inst)));
            build.vmulsd(inst.regX64, inst.regX64, lowering.memRegDoubleOp(OP_B(inst)));
        }
        else if (OP_A(inst).kind == IrOpKind::Inst)
        {
            build.vmulsd(inst.regX64, lowering.regOp(OP_A(inst)), lowering.memRegDoubleOp(OP_B(inst)));
        }
        else
        {
            CODEGEN_ASSERT(OP_B(inst).kind == IrOpKind::Inst);
            build.vmulsd(inst.regX64, lowering.regOp(OP_B(inst)), lowering.memRegDoubleOp(OP_A(inst)));
        }
        build.vaddsd(inst.regX64, inst.regX64, lowering.memRegDoubleOp(OP_C(inst)));
    }
}

inline void lower_SELECT_NUM(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;
    auto& regs = lowering.regs;
    (void)next;

    inst.regX64 = regs.allocRegOrReuse(SizeX64::xmmword, index, {OP_A(inst), OP_C(inst), OP_D(inst)});
    ScopedRegX64 tmp{regs, SizeX64::xmmword};
    if (OP_C(inst).kind == IrOpKind::Inst)
    {
        build.vcmpeqsd(tmp.reg, lowering.regOp(OP_C(inst)), lowering.memRegDoubleOp(OP_D(inst)));
    }
    else
    {
        build.vmovsd(tmp.reg, lowering.memRegDoubleOp(OP_C(inst)));
        build.vcmpeqsd(tmp.reg, tmp.reg, lowering.memRegDoubleOp(OP_D(inst)));
    }
    if (OP_A(inst).kind == IrOpKind::Inst)
    {
        build.vblendvpd(inst.regX64, lowering.regOp(OP_A(inst)), lowering.memRegDoubleOp(OP_B(inst)), tmp.reg);
    }
    else
    {
        build.vmovsd(inst.regX64, lowering.memRegDoubleOp(OP_A(inst)));
        build.vblendvpd(inst.regX64, inst.regX64, lowering.memRegDoubleOp(OP_B(inst)), tmp.reg);
    }
}

