    div_rdx.take(rdx);
    build.mov(rax, lowering.memRegInt64Op(OP_A(inst)));
    build.cqo();
    build.idiv(lowering.memRegInt64Op(OP_B(inst)));
    inst.regX64 = regs.allocRegOrReuse(SizeX64::qword, index, {OP_A(inst), OP_B(inst)});
