inline void lower_BITLSHIFT_UINT(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;
    auto& regs = lowering.regs;
    (void)next;

    auto shift_tmp = ScopedRegX64{regs};
    if (!(OP_B(inst).kind == IrOpKind::Constant))
    {
        shift_tmp.take(ecx);
    }
    inst.regX64 = regs.allocRegOrReuse(SizeX64::dword, index, {OP_A(inst)});
    if ((OP_A(inst).kind != IrOpKind::Inst || inst.regX64 != lowering.regOp(OP_A(inst))))
    {
        build.mov(inst.regX64, lowering.memRegUintOp(OP_A(inst)));
    }
    if (OP_B(inst).kind == IrOpKind::Constant)
    {
        build.shl(inst.regX64, int8_t(unsigned(lowering.intOp(OP_B(inst)))));
    }
    else
    {
        build.mov(shift_tmp.reg, lowering.memRegUintOp(OP_B(inst)));
        build.shl(inst.regX64, byteReg(shift_tmp.reg));
    }
}

