inline void lower_BITARSHIFT_INT64(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;
    auto& regs = lowering.regs;
    (void)next;

    auto shift_tmp = ScopedRegX64{regs};
    if (!(OP_B(inst).kind == IrOpKind::Constant))
    {
        shift_tmp.take(rcx);
    }
    inst.regX64 = regs.allocRegOrReuse(SizeX64::qword, index, {OP_A(inst)});
    if ((OP_A(inst).kind != IrOpKind::Inst || inst.regX64 != lowering.regOp(OP_A(inst))))
    {
        build.mov(inst.regX64, lowering.memRegInt64Op(OP_A(inst)));
    }
    if (OP_B(inst).kind == IrOpKind::Constant)
    {
        if (lowering.int64Op(OP_B(inst)) < -63)
        {
            build.xor_(inst.regX64, inst.regX64);
        }
        else if (lowering.int64Op(OP_B(inst)) < 0)
        {
            build.shl(inst.regX64, int8_t(uint8_t(-lowering.int64Op(OP_B(inst)))));
        }
        else if (lowering.int64Op(OP_B(inst)) > 63)
        {
            build.sar(inst.regX64, int8_t(63));
        }
        else
        {
            build.sar(inst.regX64, int8_t(lowering.int64Op(OP_B(inst))));
        }
    }
    else
    {
        ScopedRegX64 tmp{regs, SizeX64::qword};
        Label negative;
        Label out_of_range_positive;
        Label out_of_range_negative;
        Label done;
        build.mov(shift_tmp.reg, lowering.memRegInt64Op(OP_B(inst)));
        build.cmp(shift_tmp.reg, 63);
        build.jcc(ConditionX64::Greater, out_of_range_positive);
        build.lea(tmp.reg, addr[shift_tmp.reg + 63]);
        build.test(tmp.reg, tmp.reg);
        build.jcc(ConditionX64::Less, out_of_range_negative);
        build.test(shift_tmp.reg, shift_tmp.reg);
        build.jcc(ConditionX64::Less, negative);
        build.sar(inst.regX64, byteReg(shift_tmp.reg));
        build.jmp(done);
        build.setLabel(negative);
        build.neg(shift_tmp.reg);
        build.shl(inst.regX64, byteReg(shift_tmp.reg));
        build.jmp(done);
        build.setLabel(out_of_range_positive);
        build.sar(inst.regX64, int8_t(63));
        build.jmp(done);
        build.setLabel(out_of_range_negative);
        build.xor_(inst.regX64, inst.regX64);
        build.setLabel(done);
    }
}

