inline void lower_CMP_ANY(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;
    auto& regs = lowering.regs;
    (void)next;

    CODEGEN_ASSERT(OP_A(inst).kind == IrOpKind::VmReg && OP_B(inst).kind == IrOpKind::VmReg);
    inst.regX64 = regs.allocReg(SizeX64::dword, index);
    Label skip;
    Label exit;
    if (conditionOp(OP_C(inst)) == IrCondition::Equal)
    {
        ScopedRegX64 tmp{regs, SizeX64::dword};
        build.mov(tmp.reg, lowering.memRegTagOp(OP_A(inst)));
        build.cmp(lowering.memRegTagOp(OP_B(inst)), tmp.reg);
        build.jcc(ConditionX64::NotEqual, skip);
    }
    {
        auto spill_guard = ScopedSpills(regs);
        auto call_wrap = IrCallWrapperX64(regs, build);
        call_wrap.addArgument(SizeX64::qword, rState);
        call_wrap.addArgument(SizeX64::qword, luauRegAddress(vmRegOp(OP_A(inst))));
        call_wrap.addArgument(SizeX64::qword, luauRegAddress(vmRegOp(OP_B(inst))));
        call_wrap.setResultRegister(inst.regX64, index);
        if (conditionOp(OP_C(inst)) == IrCondition::LessEqual)
        {
            call_wrap.call(qword[rNativeContext + offsetof(NativeContext, luaV_lessequal)]);
        }
        else if (conditionOp(OP_C(inst)) == IrCondition::Less)
        {
            call_wrap.call(qword[rNativeContext + offsetof(NativeContext, luaV_lessthan)]);
        }
        else if (conditionOp(OP_C(inst)) == IrCondition::Equal)
        {
            call_wrap.call(qword[rNativeContext + offsetof(NativeContext, luaV_equalval)]);
        }
        else
        {
            CODEGEN_ASSERT(!"Unsupported instruction form");
        }
        emitUpdateBase(build);
    }
    if (conditionOp(OP_C(inst)) == IrCondition::Equal)
    {
        build.jmp(exit);
        build.setLabel(skip);
        build.xor_(inst.regX64, inst.regX64);
        build.setLabel(exit);
    }
}

inline void lower_JUMP_EQ_TAG(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;
    (void)index;

    CODEGEN_ASSERT(OP_B(inst).kind == IrOpKind::Inst || OP_B(inst).kind == IrOpKind::Constant);
    auto opb = OP_B(inst).kind == IrOpKind::Inst ? lowering.regOp(OP_B(inst)) : OperandX64(lowering.tagOp(OP_B(inst)));
    if (OP_A(inst).kind == IrOpKind::Constant)
    {
        build.cmp(opb, lowering.tagOp(OP_A(inst)));
    }
    else
    {
        build.cmp(lowering.memRegTagOp(OP_A(inst)), opb);
    }
    if (lowering.isFallthroughBlock(lowering.blockOp(OP_D(inst)), next))
    {
        build.jcc(ConditionX64::Equal, lowering.labelOp(OP_C(inst)));
        lowering.jumpOrFallthrough(lowering.blockOp(OP_D(inst)), next);
    }
    else
    {
        build.jcc(ConditionX64::NotEqual, lowering.labelOp(OP_D(inst)));
        lowering.jumpOrFallthrough(lowering.blockOp(OP_C(inst)), next);
    }
}

