inline void lower_CHECK_ARRAY_SIZE(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;

    if (OP_B(inst).kind == IrOpKind::Inst)
    {
        build.cmp(dword[lowering.regOp(OP_A(inst)) + offsetof(LuaTable, sizearray)], lowering.regOp(OP_B(inst)));
    }
    else if (OP_B(inst).kind == IrOpKind::Constant)
    {
        build.cmp(dword[lowering.regOp(OP_A(inst)) + offsetof(LuaTable, sizearray)], lowering.intOp(OP_B(inst)));
    }
    else
    {
        CODEGEN_ASSERT(!"Unsupported instruction form");
    }
    lowering.jumpOrAbortOnUndef(ConditionX64::BelowEqual, OP_C(inst), index, next);
}

