    CODEGEN_ASSERT(OP_B(inst).kind == IrOpKind::VmReg);
    CODEGEN_ASSERT(OP_C(inst).kind == IrOpKind::Constant);
    if (lowering.intOp(OP_C(inst)) == LUA_MULTRET)
    {
        auto call_wrap = IrCallWrapperX64(regs, build);
        call_wrap.addArgument(SizeX64::qword, rState);
        auto reg = call_wrap.suggestNextArgumentRegister(SizeX64::qword);
        build.mov(reg, sCode);
        call_wrap.addArgument(SizeX64::qword, addr[reg + (lowering.uintOp(OP_A(inst)) * sizeof(Instruction))]);
        call_wrap.addArgument(SizeX64::qword, rBase);
        call_wrap.addArgument(SizeX64::dword, vmRegOp(OP_B(inst)));
        call_wrap.call(qword[rNativeContext + offsetof(NativeContext, executeGETVARARGSMultRet)]);
        emitUpdateBase(build);
    }
    else
    {
        auto call_wrap = IrCallWrapperX64(regs, build);
        call_wrap.addArgument(SizeX64::qword, rState);
        call_wrap.addArgument(SizeX64::qword, rBase);
        call_wrap.addArgument(SizeX64::dword, vmRegOp(OP_B(inst)));
        call_wrap.addArgument(SizeX64::dword, lowering.intOp(OP_C(inst)));
        call_wrap.call(qword[rNativeContext + offsetof(NativeContext, executeGETVARARGSConst)]);
    }
