inline void lower_GET_CACHED_IMPORT(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;
    auto& regs = lowering.regs;
    (void)next;

    regs.assertAllFree();
    regs.assertNoSpills();
    Label skip;
    Label exit;
    build.cmp(luauConstantTag(vmConstOp(OP_B(inst))), LUA_TNIL);
    build.jcc(ConditionX64::NotEqual, skip);
    {
        auto spill_guard = ScopedSpills(regs);
        auto call_wrap = IrCallWrapperX64(regs, build, index);
        call_wrap.addArgument(SizeX64::qword, rState);
        call_wrap.addArgument(SizeX64::qword, luauRegAddress(vmRegOp(OP_A(inst))));
        call_wrap.addArgument(SizeX64::dword, lowering.importOp(OP_C(inst)));
        call_wrap.addArgument(SizeX64::dword, lowering.uintOp(OP_D(inst)));
        call_wrap.call(qword[rNativeContext + offsetof(NativeContext, getImport)]);
        emitUpdateBase(build);
    }
    build.jmp(exit);
    build.setLabel(skip);
    ScopedRegX64 tmp1{regs, SizeX64::xmmword};
    build.vmovups(tmp1.reg, luauConstant(vmConstOp(OP_B(inst))));
    build.vmovups(luauReg(vmRegOp(OP_A(inst))), tmp1.reg);
    build.setLabel(exit);
}

inline void lower_TRY_CALL_FASTGETTM(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;
    auto& regs = lowering.regs;
    (void)next;

    inst.regX64 = regs.allocReg(SizeX64::qword, index);
    auto tmp = ScopedRegX64{regs};
    tmp.alloc(SizeX64::qword);
    build.mov(tmp.reg, qword[lowering.regOp(OP_A(inst)) + offsetof(LuaTable, metatable)]);
    regs.freeLastUseReg(lowering.function.instOp(OP_A(inst)), index);
    build.test(tmp.reg, tmp.reg);
    build.jcc(ConditionX64::Zero, lowering.labelOp(OP_C(inst)));
    build.test(byte[tmp.reg + offsetof(LuaTable, tmcache)], (1 << lowering.intOp(OP_B(inst))));
    build.jcc(ConditionX64::NotZero, lowering.labelOp(OP_C(inst)));
    auto tmp2 = ScopedRegX64{regs};
    tmp2.alloc(SizeX64::qword);
    build.mov(tmp2.reg, qword[rState + offsetof(lua_State, global)]);
    {
        auto spill_guard = ScopedSpills(regs);
        auto call_wrap = IrCallWrapperX64(regs, build, index);
        call_wrap.addArgument(SizeX64::qword, tmp);
        call_wrap.addArgument(SizeX64::qword, lowering.intOp(OP_B(inst)));
        call_wrap.addArgument(SizeX64::qword, qword[tmp2.release() + offsetof(global_State, tmname) + lowering.intOp(OP_B(inst)) * sizeof(TString*)]);
        call_wrap.setResultRegister(inst.regX64, index);
        call_wrap.call(qword[rNativeContext + offsetof(NativeContext, luaT_gettm)]);
    }
    build.test(inst.regX64, inst.regX64);
    build.jcc(ConditionX64::Zero, lowering.labelOp(OP_C(inst)));
}

