inline void lower_INVOKE_FASTCALL(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;
    auto& regs = lowering.regs;
    (void)next;

    auto args_alt = ScopedRegX64{regs};
    if (!(OP_E(inst).kind == IrOpKind::Undef))
    {
        ScopedRegX64 tmp{regs, SizeX64::xmmword};
        CODEGEN_ASSERT(lowering.intOp(OP_F(inst)) == 3);
        args_alt.alloc(SizeX64::qword);
        build.mov(args_alt.reg, qword[rState + offsetof(lua_State, top)]);
        build.vmovups(tmp.reg, luauReg(vmRegOp(OP_D(inst))));
        build.vmovups(xmmword[args_alt.reg], tmp.reg);
        build.vmovups(tmp.reg, luauReg(vmRegOp(OP_E(inst))));
        build.vmovups(xmmword[args_alt.reg + sizeof(TValue)], tmp.reg);
    }
    else
    {
        if (!(OP_D(inst).kind == IrOpKind::VmReg || OP_D(inst).kind == IrOpKind::VmConst))
        {
            CODEGEN_ASSERT(OP_D(inst).kind == IrOpKind::Undef);
        }
    }
    auto args_op = !(OP_E(inst).kind == IrOpKind::Undef) ? OperandX64(0) : (OP_D(inst).kind == IrOpKind::VmReg ? luauRegAddress(vmRegOp(OP_D(inst))) : (OP_D(inst).kind == IrOpKind::VmConst ? luauConstantAddress(vmConstOp(OP_D(inst))) : OperandX64(0)));
    auto call_wrap = IrCallWrapperX64(regs, build, index);
    call_wrap.addArgument(SizeX64::qword, rState);
    call_wrap.addArgument(SizeX64::qword, luauRegAddress(vmRegOp(OP_B(inst))));
    call_wrap.addArgument(SizeX64::qword, luauRegAddress(vmRegOp(OP_C(inst))));
    call_wrap.addArgument(SizeX64::dword, lowering.intOp(OP_G(inst)));
    if (!(OP_E(inst).kind == IrOpKind::Undef))
    {
        call_wrap.addArgument(SizeX64::qword, args_alt);
    }
    else
    {
        call_wrap.addArgument(SizeX64::qword, args_op);
    }
    if (lowering.intOp(OP_F(inst)) == LUA_MULTRET)
    {
        auto reg = call_wrap.suggestNextArgumentRegister(SizeX64::qword);
        ScopedRegX64 tmp{regs, SizeX64::qword};
        build.mov(reg, qword[rState + offsetof(lua_State, top)]);
        build.lea(tmp.reg, addr[rBase + ((vmRegOp(OP_B(inst)) + 1) * sizeof(TValue))]);
        build.sub(reg, tmp.reg);
        build.shr(reg, kTValueSizeLog2);
        call_wrap.addArgument(SizeX64::dword, dwordReg(reg));
    }
    else
    {
        call_wrap.addArgument(SizeX64::dword, lowering.intOp(OP_F(inst)));
    }
    auto func = ScopedRegX64{regs};
    func.alloc(SizeX64::qword);
    build.mov(func.reg, qword[rNativeContext + offsetof(NativeContext, luauF_table) + lowering.uintOp(OP_A(inst)) * sizeof(luau_FastFunction)]);
    call_wrap.call(func.release());
    inst.regX64 = regs.takeReg(eax, index);
}

inline void lower_INVOKE_LIBM(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;
    auto& regs = lowering.regs;
    (void)next;

    auto call_wrap = IrCallWrapperX64(regs, build, index);
    call_wrap.addArgument(SizeX64::xmmword, lowering.memRegDoubleOp(OP_B(inst)), OP_B(inst));
    if (HAS_OP_C(inst))
    {
        auto is_int = (OP_C(inst).kind == IrOpKind::Constant ? lowering.function.constOp(OP_C(inst)).kind == IrConstKind::Int : getCmdValueKind(lowering.function.instOp(OP_C(inst)).cmd) == IrValueKind::Int);
        if (is_int)
        {
            call_wrap.addArgument(SizeX64::dword, lowering.memRegUintOp(OP_C(inst)), OP_C(inst));
        }
        else
        {
            call_wrap.addArgument(SizeX64::xmmword, lowering.memRegDoubleOp(OP_C(inst)), OP_C(inst));
        }
    }
    call_wrap.call(qword[rNativeContext + getNativeContextOffset(lowering.uintOp(OP_A(inst)))]);
    inst.regX64 = regs.takeReg(xmm0, index);
}

inline void lower_FORGLOOP(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;
    auto& regs = lowering.regs;
    (void)index;

    regs.assertAllFree();
    emitInstForGLoop(regs, build, vmRegOp(OP_A(inst)), lowering.intOp(OP_B(inst)), lowering.labelOp(OP_C(inst)));
    lowering.jumpOrFallthrough(lowering.blockOp(OP_D(inst)), next);
}

inline void lower_FORGLOOP_FALLBACK(IrLoweringX64& lowering, IrInst& inst, uint32_t index, const IrBlock& next)
{
    auto& build = lowering.build;
    auto& regs = lowering.regs;

    auto call_wrap = IrCallWrapperX64(regs, build, index);
    call_wrap.addArgument(SizeX64::qword, rState);
    call_wrap.addArgument(SizeX64::dword, vmRegOp(OP_A(inst)));
    call_wrap.addArgument(SizeX64::dword, lowering.intOp(OP_B(inst)));
    if (FFlag::LuauYieldIter2)
    {
        call_wrap.call(qword[rNativeContext + offsetof(NativeContext, forgLoopNonTableFallback)]);
        emitUpdateBase(build);
        build.test(eax, eax);
        build.jcc(ConditionX64::Less, lowering.helpers.exitNoContinueVm);
        build.jcc(ConditionX64::Greater, lowering.labelOp(OP_C(inst)));
    }
    else
    {
        call_wrap.call(qword[rNativeContext + offsetof(NativeContext, forgLoopNonTableFallback_DEPRECATED)]);
        emitUpdateBase(build);
        build.test(al, al);
        build.jcc(ConditionX64::NotZero, lowering.labelOp(OP_C(inst)));
    }
    lowering.jumpOrFallthrough(lowering.blockOp(OP_D(inst)), next);
}

